import{useEffect,useState}from"react";import{Link,useNavigate,useParams,useLocation,Routes,Route,Navigate}from"react-router-dom";import{Package,Truck,MapPin,ShieldCheck,Plus,Search,LogOut,ArrowRight,CheckCircle2,Clock3,Users,PackageCheck,Copy,ExternalLink,UserRound}from"lucide-react";
const API=(import.meta.env.VITE_API_URL||"https://logisticsfav-api.onrender.com/api").replace(/\/$/,"");
const token=()=>localStorage.getItem("logistics_token");
const savedUser=()=>{try{return JSON.parse(localStorage.getItem("logistics_user")||"null")}catch{return null}};

async function api(path,opt={}){
  const attempts=3;
  let lastError;
  for(let attempt=0;attempt<attempts;attempt++){
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),35000);
    try{
      const headers={"Content-Type":"application/json",...(token()?{Authorization:"Bearer "+token()}: {}),...(opt.headers||{})};
      const r=await fetch(API+path,{...opt,headers,signal:controller.signal});
      const d=await r.json().catch(()=>({}));
      if(r.ok)return d;
      const e=Error(r.status===429?"Too many requests. Please wait a moment and try again.":d.message||("Request failed ("+r.status+")"));
      e.status=r.status;
      if((r.status===502||r.status===503||r.status===504)&&attempt<attempts-1){
        await new Promise(resolve=>setTimeout(resolve,1200));
        lastError=e;
        continue;
      }
      throw e;
    }catch(e){
      lastError=e;
      if(e.name==="AbortError"||e.code==="NETWORK"||e instanceof TypeError){
        if(attempt<attempts-1){
          await new Promise(resolve=>setTimeout(resolve,1500));
          continue;
        }
        const x=Error("Unable to connect right now. Please try again.");
        x.code="NETWORK";
        throw x;
      }
      throw e;
    }finally{clearTimeout(timeout)}
  }
  throw lastError||Error("Unable to reach E-LOGS server. Please try again.");
}
function useAuth(){
  const[user,setUser]=useState(()=>savedUser()),[loading,setLoading]=useState(true);
  useEffect(()=>{
    const saved=token();
    if(!saved){setLoading(false);return;}
    // Keep the last known user visible while the session is checked. Temporary 429/network errors must not look like a logout.
    api("/auth/me").then(d=>{setUser(d.user);localStorage.setItem("logistics_user",JSON.stringify(d.user))}).catch(e=>{
      if(e.status===401||e.status===403){localStorage.removeItem("logistics_token");localStorage.removeItem("logistics_user");setUser(null);}
    }).finally(()=>setLoading(false));
  },[]);
  return{user,setUser,loading}
}

function ScrollToTop(){const{pathname}=useLocation();useEffect(()=>{window.scrollTo({top:0,left:0,behavior:"auto"})},[pathname]);return null}
function NotFound(){return <main className="mx-auto grid min-h-[70vh] max-w-3xl place-items-center px-4 py-16 text-center"><div><p className="font-black tracking-widest text-teal-700">404</p><h1 className="mt-3 text-5xl font-black">Page not found</h1><p className="mt-4 text-slate-500">The page you are looking for does not exist, or the link has changed.</p><div className="mt-7 flex justify-center gap-3"><Link className="primary" to="/">Back home</Link><Link className="secondary" to="/track">Track a shipment</Link></div></div></main>}
